:root {
  --bg-card: #1a1a2e;
  --bg-wall: #16213e;
  --bg-stat: #0f3460;
  --bg-highlight: #e94560;
  --bg-header: #12122a;
  --accent-neon: #00f5d4;
  --accent-yellow: #f9c74f;
  --accent-red: #e94560;
  --color-text-primary: #e8e8f0;
  --color-text-muted: #8888aa;
  --color-tag: #2a2a4a;
  --color-tag-text: #00f5d4;
  --dot-fail: #e94560;
  --dot-send: #00f5d4;
  --dot-empty: #2a2a4a;
  --hold-color: #00f5d4;
  --hold-start: #f9c74f;
  --hold-top: #e94560;
  --border-subtle: #2a2a50;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.route-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: 16px;
  width: 480px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.route-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-subtle);
}

.grade-badge {
  background: var(--accent-neon);
  color: var(--bg-card);
  font-size: 22px;
  font-weight: 900;
  border-radius: 10px;
  width: 52px;
  height: 52px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  letter-spacing: -1px;
}

.route-meta {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.route-name {
  font-size: 18px;
  font-weight: 800;
  color: var(--color-text-primary);
  line-height: 1.1;
}

.route-setter {
  font-size: 12px;
  color: var(--color-text-muted);
}

.route-setter strong {
  color: var(--accent-yellow);
  font-weight: 600;
}

.status-pill {
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.status-pill.active {
  background: var(--accent-neon);
  color: var(--bg-card);
}

.route-body {
  display: flex;
  flex-direction: row;
  gap: 0;
  flex: 1;
}

.wall-diagram {
  background: var(--bg-wall);
  width: 140px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 8px 8px;
  border-right: 1px solid var(--border-subtle);
  gap: 8px;
}

.wall-surface {
  flex: 1;
  width: 100%;
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: repeat(2, 1fr);
  gap: 10px;
  padding: 8px;
  background: var(--bg-card);
  border-radius: 8px;
  border: 1px solid var(--border-subtle);
  min-height: 110px;
}

.hold {
  font-size: 16px;
  color: var(--hold-color);
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.hold.start {
  color: var(--hold-start);
}

.hold.top {
  color: var(--hold-top);
  font-size: 18px;
}

.wall-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

.route-stats {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto auto;
  gap: 8px;
  padding: 12px;
  align-content: start;
}

.stat-block {
  background: var(--bg-stat);
  border-radius: 10px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.stat-block.highlight {
  background: var(--bg-highlight);
}

.stat-value {
  font-size: 20px;
  font-weight: 800;
  color: var(--color-text-primary);
  line-height: 1;
}

.stat-label {
  font-size: 11px;
  color: var(--color-text-muted);
  font-weight: 500;
}

.stat-block.highlight .stat-label {
  color: rgba(232, 232, 240, 0.75);
}

.tag-row {
  grid-column: 1 / -1;
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.tag {
  background: var(--color-tag);
  color: var(--color-tag-text);
  font-size: 11px;
  font-weight: 600;
  padding: 4px 9px;
  border-radius: 20px;
  border: 1px solid var(--accent-neon);
}

.route-footer {
  background: var(--bg-header);
  border-top: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  gap: 12px;
}

.attempts {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.attempts-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.attempt-dots {
  display: flex;
  gap: 5px;
  align-items: center;
}

.dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
}

.dot.fail {
  background: var(--dot-fail);
}

.dot.send {
  background: var(--dot-send);
}

.dot.empty {
  background: var(--dot-empty);
  border: 1px solid var(--border-subtle);
}

.footer-right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.expires {
  font-size: 11px;
  color: var(--color-text-muted);
}

.log-btn {
  background: var(--accent-neon);
  color: var(--bg-card);
  border: none;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 700;
  padding: 8px 16px;
  cursor: pointer;
}
